From worktree audit. First step: port tests only (not old code, rejected wave 11) and run on main. Code reading, not run: nyquistCrossover gates D!=0 on max(solve,coeffs), would return no pi. File margin.go. Do not start ahead of CORE. Source archive/wt-399b534 margin_nyquist_zero_test.go, TestAllMarginNyquistBiproperPencilPi, ...BiproperCluster:
```go
package controlsys

import (
	"math"
	"math/big"
	"math/cmplx"
	"math/rand/v2"
	"slices"
	"testing"
)

// CMVMWK: π is a crossover iff L(−1) of the coefficients as given, exact in
// big floats, is negative, as MATLAB evaluates them; with an exact (z+1)
// factor L(−1) = 0 and π is none, and a k·(z+1)⁴ cluster rounded to
// L(−1) ~ −1e-19, below the coefficient-rounding bound, is one.
// 6OPXWW: beside a zero cluster at z = −1, as of num ≈ k·(z+1)⁴, the pencil
// roots of L − L~ fall up to ~1e-4 off a phase crossover within that of
// Nyquist, where |L| ~ 1e-18, beyond any polish bracket; it was dropped.
// Oracle: the expanded coefficients evaluated in big floats, bisected on a
// grid graded to Nyquist; the repro and a seeded sweep of perturbed
// k·(z+1)⁴ over stable fifth-order denominators.
func TestAllMarginPhaseCrossNyquistZeroCluster(t *testing.T) {
	type tc struct{ num, den []float64 }
	cases := []tc{{
		[]float64{-0.0031586889782527225, -0.012630121036594033, -0.01893823083182162, -0.01262085446680662, -0.0031540556933263115},
		[]float64{1, -3.839652412015958, 5.8306455706710025, -4.376107218517926, 1.623325246208784, -0.2381308105407497},
	}}
	rng := rand.New(rand.NewPCG(61, 67))
	for i := range 80 {
		num := []float64{math.Copysign(math.Pow(10, -3+2*rng.Float64()), rng.Float64()-0.5)}
		for j := range 4 {
			d := math.Copysign(math.Pow(10, -4+2*rng.Float64()), rng.Float64()-0.5)
			if i%2 == 0 && j == 0 {
				d = 0
			}
			num = polyMul(num, []float64{1, 1 - d})
		}
		den := []float64{1, -(0.9 - 1.8*rng.Float64())}
		for range 2 {
			rho, phi := 0.3+0.65*rng.Float64(), math.Pi*rng.Float64()/2
			den = polyMul(den, []float64{1, -2 * rho * math.Cos(phi), rho * rho})
		}
		cases = append(cases, tc{num, den})
	}
	loop := func(c tc, th float64) complex128 { return bigHorner(c.num, th) / bigHorner(c.den, th) }
	var nearNyquist, exactZero, clusterPi int
	for ci, c := range cases {
		phase := func(th float64) float64 { return phaseOffsetDeg(loop(c, th)) }
		var thp []float64
		const N = 20000
		for i := 2; i < N; i++ {
			a, b := math.Pi*(1-math.Pow(1-float64(i-1)/N, 3)), math.Pi*(1-math.Pow(1-float64(i)/N, 3))
			pa, pb := phase(a), phase(b)
			if (pa > 0) == (pb > 0) || math.Abs(pa) >= 90 || math.Abs(pb) >= 90 {
				continue
			}
			for range 200 {
				m := (a + b) / 2
				if m <= a || m >= b {
					break
				}
				if pm := phase(m); (pm > 0) == (pa > 0) {
					a, pa = m, pm
				} else {
					b = m
				}
			}
			thp = append(thp, (a+b)/2)
		}
		if slices.ContainsFunc(thp, func(th float64) bool { return th > math.Pi-1e-3 }) {
			nearNyquist++
		}
		r, err := (&TransferFunc{Num: [][][]float64{{c.num}}, Den: [][]float64{c.den}, Dt: 1}).StateSpace()
		if err != nil {
			t.Fatal(err)
		}
		res, err := AllMargin(r.Sys)
		if err != nil {
			t.Fatalf("case %d: %v", ci, err)
		}
		got, gm := res.PhaseCrossFreqs, res.GainMargins
		gotPi := len(got) > 0 && got[len(got)-1] == math.Pi
		if gotPi {
			got, gm = got[:len(got)-1], gm[:len(gm)-1]
		}
		var scale float64
		for _, v := range c.num {
			scale += math.Abs(v)
		}
		nyq := polyAtMinusOne(c.num, c.den)
		if n, _ := polyAtMinusOne(c.num, []float64{1}).Float64(); math.Abs(n) <= 1e-13*scale {
			if nyq.Sign() == 0 {
				exactZero++
			} else if nyq.Sign() < 0 {
				clusterPi++
			}
		}
		lm1, _ := nyq.Float64()
		ok := len(got) == len(thp) && gotPi == (nyq.Sign() < 0)
		if gotPi {
			ok = ok && math.Abs(res.GainMargins[len(got)]+20*math.Log10(math.Abs(lm1))) <= 1e-5
		}
		for i := 0; ok && i < len(thp); i++ {
			th := thp[i]
			ok = math.Abs(got[i]-th) <= 1e-7*th && math.Abs(gm[i]+20*math.Log10(cmplx.Abs(loop(c, th)))) <= 1e-5
		}
		if !ok {
			t.Errorf("case %d num %v den %v: θpc %v gm %v, want θ %v", ci, c.num, c.den, res.PhaseCrossFreqs, res.GainMargins, thp)
		}
	}
	if nearNyquist < 10 {
		t.Errorf("only %d cases cross within 1e-3 of Nyquist", nearNyquist)
	}
	if exactZero < 3 || clusterPi < 10 {
		t.Errorf("only %d exact zeros and %d negative L(−1) at |N(−1)| ≤ 1e-13·‖num‖₁", exactZero, clusterPi)
	}
}

// polyAtMinusOne is num(−1)/den(−1) of the coefficients as given, exactly.
func polyAtMinusOne(num, den []float64) *big.Float {
	at := func(p []float64) *big.Float {
		s := new(big.Float).SetPrec(3000)
		for i, c := range p {
			v := new(big.Float).SetPrec(3000).SetFloat64(c)
			if (len(p)-1-i)%2 == 1 {
				v.Neg(v)
			}
			s.Add(s, v)
		}
		return s
	}
	return new(big.Float).SetPrec(3000).Quo(at(num), at(den))
}

// 6OPXWW: beside an exact zero cluster at z = −1 the scan towards Nyquist
// took a sign change of rounding residue, |L| ~ 1e-41, for a crossover, and
// L(−1) of ~1 ulp of |D| for one at Nyquist. Oracle: the coefficients in big
// floats, whose phase at the reported crossover tends to 0°, not −180°, and
// the crossovers below 3 found as before.
func TestAllMarginNyquistZeroClusterNoise(t *testing.T) {
	cases := []struct {
		num, den, want []float64
	}{
		{
			[]float64{0.004446950175721477, 0.01778780070288591, 0.026681701054328863, 0.01778780070288591, 0.004446950175721477},
			[]float64{1, 0.5924323257687443, 0.17033971248001745, 0.08044852775749614, -0.13270444245004534, -0.27271221810899804, -0.1506786024130224, 0.012149078195984445, 0.007692746757699009},
			[]float64{0.55129690992, 1.61388467294, 2.67343541852},
		},
		{
			[]float64{-0.004387008771532378, -0.01735277121673983, -0.025736271196440508, -0.016962263828791034, -0.004191755077557978},
			[]float64{1, 0.04447989509354311, -0.9820837702600874, -0.033079139783047384, 0.2251477532922962},
			nil,
		},
		{
			[]float64{-0.6955939875900586, -1.3911879751801173, -0.6955939875900586},
			[]float64{1, -0.20632506540049872, -0.12389966592884397},
			nil,
		},
	}
	for i, c := range cases {
		for _, d := range []float64{1e-6, 1e-8} {
			if p := phaseOffsetDeg(bigHornerBeforeNyquist(c.num, d) / bigHornerBeforeNyquist(c.den, d)); math.Abs(math.Abs(p)-180) > 2 {
				t.Fatalf("case %d: oracle phase offset %g° at π−%g, want ±180°", i, p, d)
			}
		}
		r, err := (&TransferFunc{Num: [][][]float64{{c.num}}, Den: [][]float64{c.den}, Dt: 1}).StateSpace()
		if err != nil {
			t.Fatal(err)
		}
		res, err := AllMargin(r.Sys)
		if err != nil {
			t.Fatalf("case %d: %v", i, err)
		}
		var got []float64
		for _, w := range res.PhaseCrossFreqs {
			if w > 3 {
				t.Errorf("case %d: crossover %.17g (GM %g dB), want none above 3", i, w, res.GainMargins[len(got)])
			} else {
				got = append(got, w)
			}
		}
		ok := len(got) == len(c.want)
		for k := 0; ok && k < len(got); k++ {
			ok = math.Abs(got[k]-c.want[k]) <= 1e-9*c.want[k]
		}
		if !ok {
			t.Errorf("case %d: θpc %v, want %v", i, res.PhaseCrossFreqs, c.want)
		}
	}
}

// bigHornerBeforeNyquist is bigHorner at θ = π − d with z = −1 + 2sin²(d/2)
// + j·sin d, which keeps z + 1 to full relative precision.
func bigHornerBeforeNyquist(p []float64, d float64) complex128 {
	nf := func(x float64) *big.Float { return new(big.Float).SetPrec(300).SetFloat64(x) }
	sh := math.Sin(d / 2)
	zr := nf(-1)
	zr.Add(zr, nf(2*sh*sh))
	zi := nf(math.Sin(d))
	re, im, t1, t2 := nf(0), nf(0), nf(0), nf(0)
	for _, c := range p {
		nr := nf(0).Sub(t1.Mul(re, zr), t2.Mul(im, zi))
		im.Add(t1.Mul(re, zi), t2.Mul(im, zr))
		re.Add(nr, nf(c))
	}
	r, _ := re.Float64()
	i, _ := im.Float64()
	return complex(r, i)
}

// L real negative at Nyquist is a crossover unless L is real on the whole
// boundary, which has no isolated crossings.
func TestAllMarginDiscreteNyquistRealEnd(t *testing.T) {
	cases := []struct {
		num, den []float64
		want     []float64
	}{
		{[]float64{-3}, []float64{1}, nil},
		{[]float64{-2, 0}, []float64{1, 0}, nil},
		{[]float64{0.5}, []float64{1, 0.5}, []float64{math.Pi}},
	}
	for _, c := range cases {
		r, err := (&TransferFunc{Num: [][][]float64{{c.num}}, Den: [][]float64{c.den}, Dt: 1}).StateSpace()
		if err != nil {
			t.Fatal(err)
		}
		res, err := AllMargin(r.Sys)
		if err != nil {
			t.Fatal(err)
		}
		if !slices.Equal(res.PhaseCrossFreqs, c.want) {
			t.Errorf("num %v den %v: θpc %v, want %v", c.num, c.den, res.PhaseCrossFreqs, c.want)
		}
	}
}

// 3FHD47: the scan towards Nyquist solved in double-double at each of ~50
// points, O(n³) each, most of AllMargin's time on high-order discrete loops.
// It keeps the double solve where |L| is far above the coefficient noise and
// the phase offset is not small; the crossings stay those of phaseCrossings.
func TestNyquistPhaseCrossingsScanCost(t *testing.T) {
	for kind := range sweepModelKinds {
		r, err := newRationalLoop(marginRandomLoop(t, 60, kind, 0.05, false, false))
		if err != nil {
			t.Fatal(err)
		}
		ws, err := r.phaseCrossings()
		if err != nil {
			t.Fatal(err)
		}
		r.eval.ddSolves = 0
		f := func(w float64) float64 { return phaseOffsetDeg(r.eval.at(w)) }
		got := r.nyquistPhaseCrossings(slices.Clone(ws), f, 1e-7)
		if !slices.Equal(got, ws) {
			t.Errorf("%v: nyquistPhaseCrossings = %v, want %v", kind, got, ws)
		}
		if r.eval.ddSolves > 30 {
			t.Errorf("%v: %d double-double solves, want ≤ 30", kind, r.eval.ddSolves)
		}
	}
}

// CMVMWK, D ≠ 0: a biproper realization rounds C = num − D·den, so L(−1)
// of the received ss is ~an ulp of |D| whatever the coefficients as given
// say: case 406's tf L(−1) ≈ −5.1e-18 and an exact (z+1)·cluster's 0 both
// realize to −2⁻⁵⁹. With |L(−1)| ≤ eps·|D|/8 a π the pencil finds stands on
// the ss as given, as MATLAB's: if reported, the ss L(−1) is negative, at
// its gain; with |N(−1)| ≥ 1e-10·‖num‖₁ π is one iff the coefficients'
// L(−1) is negative, at its gain. Oracle: L(−1) of the tf coefficients and
// of the realization in big floats; case 406 and a seeded sweep of
// perturbed k·(z+1)³ over stable cubics.
func TestAllMarginNyquistBiproperCluster(t *testing.T) {
	type tc struct{ num, den []float64 }
	cases := []tc{{
		[]float64{-0.014807303313734897, -0.04442202472590541, -0.04442213951055694, -0.014807418098386423},
		[]float64{1, -0.20007122053124332, 0.12188596240349084, -0.03181437966453691},
	}}
	rng := rand.New(rand.NewPCG(71, 73))
	for range 400 {
		num := []float64{math.Copysign(math.Pow(10, -3+2*rng.Float64()), rng.Float64()-0.5)}
		e := -8 + 7*rng.Float64()
		for range 3 {
			d := math.Copysign(math.Pow(10, e+rng.Float64()), rng.Float64()-0.5)
			num = polyMul(num, []float64{1, 1 - d})
		}
		den := []float64{1, -(0.9 - 1.8*rng.Float64())}
		rho, phi := 0.3+0.65*rng.Float64(), math.Pi*rng.Float64()/2
		den = polyMul(den, []float64{1, -2 * rho * math.Cos(phi), rho * rho})
		cases = append(cases, tc{num, den})
	}
	var below, belowPi, above, abovePi int
	for ci, c := range cases {
		var scale float64
		for _, v := range c.num {
			scale += math.Abs(v)
		}
		n, _ := polyAtMinusOne(c.num, []float64{1}).Float64()
		lm1, _ := polyAtMinusOne(c.num, c.den).Float64()
		isBelow := ci == 0 || math.Abs(lm1) <= eps()*math.Abs(c.num[0]/c.den[0])/8
		if !isBelow && math.Abs(n) < 1e-10*scale {
			continue
		}
		r, err := (&TransferFunc{Num: [][][]float64{{c.num}}, Den: [][]float64{c.den}, Dt: 1}).StateSpace()
		if err != nil {
			t.Fatal(err)
		}
		if r.Sys.D.At(0, 0) == 0 {
			t.Fatalf("case %d: D = 0", ci)
		}
		res, err := AllMargin(r.Sys)
		if err != nil {
			t.Fatalf("case %d: %v", ci, err)
		}
		k := len(res.PhaseCrossFreqs) - 1
		gotPi := k >= 0 && res.PhaseCrossFreqs[k] == math.Pi
		var ok bool
		if isBelow {
			below++
			ok = true
			if gotPi {
				belowPi++
				h := real(bigSISOResponse(r.Sys, -1))
				ok = h < 0 && math.Abs(res.GainMargins[k]+20*math.Log10(-h)) <= 1e-5
			}
		} else {
			above++
			if lm1 < 0 {
				abovePi++
			}
			ok = gotPi == (lm1 < 0) && (!gotPi || math.Abs(res.GainMargins[k]+20*math.Log10(math.Abs(lm1))) <= 1e-5)
		}
		if !ok {
			hh, _, _, _ := ddSISOResponseNoise(r.Sys, pointAt(-1))
			t.Errorf("case %d num %v den %v: L(−1) %.3g ss %v dd %v: θpc %v gm %v", ci, c.num, c.den, lm1, bigSISOResponse(r.Sys, -1), hh, res.PhaseCrossFreqs, res.GainMargins)
		}
	}
	if below < 25 || belowPi < 3 || above < 100 || abovePi < 40 || above-abovePi < 40 {
		t.Errorf("sweep: %d below (%d π), %d above (%d negative)", below, belowPi, above, abovePi)
	}
}

// CMVMWK: the coefficient-noise gate dropped a π the pencil found, with
// D ≠ 0, where |L(−1)| ~ 4e-14·|D| lies below the first-order bound but the
// ss keeps the tf's sign, as of case 708, GM 318.2 dB, to none. Oracle:
// L(−1) of the tf coefficients and of the realization in big floats; the GM
// is the ss's and within the coefficient noise of the tf's.
func TestAllMarginNyquistBiproperPencilPi(t *testing.T) {
	cases := []struct{ num, den []float64 }{
		{[]float64{-0.002630391036392785, -0.010521181582853745, -0.015781197990452103, -0.010520415377915347, -0.002630007933924219}, []float64{1, 0.6116852553483515, -0.1820451058270926, 0.07519079155751071, -0.011213479682533143}},
		{[]float64{-0.012137441454509335, -0.04854968798534888, -0.07282441522814476, -0.0485495323182802, -0.012137363620974999}, []float64{1, 1.474985556199087, 0.0292347933647385, -0.6075078943384798, -0.14060668809352986}},
		{[]float64{0.07738458484827467, 0.2321505871097489, 0.23214741969645014, 0.07738141743497615}, []float64{1, 1.4579022674972446, 0.7027370758935293, 0.11205526439854965}},
		{[]float64{0.016037895483106832, 0.06415664448406014, 0.09624256047832874, 0.06416676943683525, 0.016042957959459807}, []float64{1, 2.6418303218423205, 2.68390424092744, 1.2359744249794358, 0.2100087249628626}},
		{[]float64{-0.009716070069349436, -0.03886428062588935, -0.058296421461571324, -0.038864281322872334, -0.009716070417840929}, []float64{1, 1.2822058977953579, -0.30979445512725645, -0.9906828654101608, -0.35102404385793096}},
	}
	for ci, c := range cases {
		lm1, _ := polyAtMinusOne(c.num, c.den).Float64()
		r, err := (&TransferFunc{Num: [][][]float64{{c.num}}, Den: [][]float64{c.den}, Dt: 1}).StateSpace()
		if err != nil {
			t.Fatal(err)
		}
		d := r.Sys.D.At(0, 0)
		h := real(bigSISOResponse(r.Sys, -1))
		_, _, noise, _ := ddSISOResponseNoise(r.Sys, pointAt(-1))
		if !(lm1 < 0 && h < 0 && math.Abs(lm1) > 1e-14*math.Abs(d) && -h < noise) {
			t.Fatalf("case %d: tf L(−1) %.3g ss %.3g noise %.3g D %.3g", ci, lm1, h, noise, d)
		}
		res, err := AllMargin(r.Sys)
		if err != nil {
			t.Fatalf("case %d: %v", ci, err)
		}
		k := len(res.PhaseCrossFreqs) - 1
		if k < 0 || res.PhaseCrossFreqs[k] != math.Pi {
			t.Errorf("case %d: θpc %v, want π", ci, res.PhaseCrossFreqs)
			continue
		}
		gm := res.GainMargins[k]
		if math.Abs(gm+20*math.Log10(-h)) > 1e-5 || math.Abs(gm+20*math.Log10(-lm1)) > 20*math.Log10(1+noise/-h) {
			t.Errorf("case %d: gm %v, ss %v, tf %v", ci, gm, -20*math.Log10(-h), -20*math.Log10(-lm1))
		}
	}
}
```

Filed from 2TUAD6 round 4 review; pre-existing, synthetic, unchanged by branch. Cross-ref 2TUAD6 residue rule. Rounded integrator cancellation beside moderately conditioned block reads Inf against the live rule. Shape: A=[A11 a12; 0 x0], c2 = rounded exact C1*inv(A11-x0 I)*a12, residues under 2.3e-16 of c2*b2. 296/1200 +/-Inf base and final native (76 cond bucket 4.5, 101 at 9.0, 119 at 13.5, 0 at 0), 298 amd64. File response.go blockLaurentGain. Generator source (PCG(7711,3); needs dcr helpers from zz_review_sweep_test.go, in git history of no branch: regenerate oracle with big.Rat):
```
func TestAdvRounded(t *testing.T) {
	f, _ := os.Create(os.Getenv("RV_ADV"))
	defer f.Close()
	w := bufio.NewWriter(f)
	defer w.Flush()
	r := rand.New(rand.NewPCG(7711, 3))
	for id := range 1200 {
		disc := id%3 == 2
		x0 := 0.0
		if disc {
			x0 = 1
		}
		nr := 1 + r.IntN(4)
		n := nr + 1
		logc := float64(id%4) * 4.5
		A := make([]float64, n*n)
		s := make([]float64, nr)
		for i := range nr {
			s[i] = math.Pow(10, -logc*float64(i)/math.Max(1, float64(nr-1)))
		}
		for i := range nr {
			A[i*n+i] = -s[i]
			for j := i + 1; j < nr; j++ {
				A[i*n+j] = r.NormFloat64()
			}
		}
		if id%8 >= 4 && nr > 1 {
			for range 2 * nr {
				p1, p2 := r.IntN(nr), r.IntN(nr)
				if p1 == p2 {
					continue
				}
				sn, cs := math.Sincos(r.Float64() * 6.28)
				for j := range nr {
					x, y := A[p1*n+j], A[p2*n+j]
					A[p1*n+j], A[p2*n+j] = cs*x-sn*y, sn*x+cs*y
				}
				for i := range nr {
					x, y := A[i*n+p1], A[i*n+p2]
					A[i*n+p1], A[i*n+p2] = cs*x-sn*y, sn*x+cs*y
				}
			}
		}
		for i := range nr {
			A[i*n+nr] = r.NormFloat64()
			A[i*n+i] += x0
		}
		A[nr*n+nr] = x0
		b := dcrRand(r, n)
		c := dcrRand(r, n)
		d := []float64{r.NormFloat64()}
		sh := make([]*big.Rat, nr*nr)
		for i := range nr {
			for j := range nr {
				sh[i*nr+j] = new(big.Rat).SetFloat64(A[i*n+j])
				if i == j {
					sh[i*nr+j].Sub(sh[i*nr+j], new(big.Rat).SetFloat64(x0))
				}
			}
		}
		inv := advInv(sh, nr)
		if inv == nil {
			continue
		}
		c1 := advRats(c[:nr])
		b1 := advRats(b[:nr])
		a12 := make([]*big.Rat, nr)
		for i := range nr {
			a12[i] = new(big.Rat).SetFloat64(A[i*n+nr])
		}
		iA := advMV(inv, nr, a12)
		exactc2, _ := advDot(c1, iA).Float64()
		c[nr] = exactc2
		ii := advMV(inv, nr, iA)
		iB := advMV(inv, nr, b1)
		b2 := new(big.Rat).SetFloat64(b[nr])
		intended := new(big.Rat).SetFloat64(d[0])
		intended.Sub(intended, advDot(c1, iB))
		intended.Sub(intended, new(big.Rat).Mul(advDot(c1, ii), b2))
		iv, _ := intended.Float64()
		res := new(big.Rat).Sub(new(big.Rat).SetFloat64(c[nr]), advDot(c1, iA))
		res.Mul(res, b2)
		rv, _ := res.Float64()
		term := math.Abs(c[nr] * b[nr])
		dt := 0.0
		if disc {
			dt = 0.1
		}
		sys, err := NewFromSlices(n, 1, 1, A, b, c, d, dt)
		if err != nil {
			continue
		}
		g := "ERR"
		if gm, err := sys.DCGain(); err == nil {
			g = fmt.Sprintf("%.17g", gm.At(0, 0))
		}
		bs := "ERR"
		if bw, e := Bandwidth(sys, -3); e == nil {
			bs = fmt.Sprintf("%.17g", bw)
		}
		ex := dcrLimit(n, 1, 1, A, b, c, d, x0)
		fmt.Fprintf(w, "%d\tcond%.1f\t%.17g\t%.17g\t%.3g\t%s\t%s\tn=%d dt=%g A=%s B=%s C=%s D=%s\n", id, logc, iv, ex[0], math.Abs(rv)/term, g, bs, n, dt, dcrFl(A), dcrFl(b), dcrFl(c), dcrFl(d))
	}
}
