			}
			k := math.Exp(math.Log(0.2) + rng.Float64()*(math.Log(2.5)-math.Log(0.2)))
			sys, twin := nearSingularEDraw(t, rng, n, m, p, k)
			if m != 1 || p != 1 {
				continue
			}
			parts, ok := foldInaccurateParts(sys)
			if !ok {
				continue
			}
			if len(parts) == 1 {
				whole++
			}
			kk, _, _ := leastSquaresIntegratorLimit(parts[0])
			if kk > 0 {
				spurK++
			}
			for _, ord := range []int{0, n - 1, 1} {
