				d, fit, err := sys.C2DFit(dt, C2DOptions{Method: C2DMethodLeastSquares, FitOrder: ord})
				if err != nil {
					continue
				}
				rows++
				ud := discreteNonStable(t, d)
				uc := twinSlowNonStable(twin)
				if ud < uc {
					udltUc++
				}
				if fit.Accuracy != 0 || ud == 0 {
					continue
				}
				acc0++
				var want []complex128
				for i := range n - 1 {
					l := twin.A.At(i, i) / twin.E.At(i, i)
					if l >= 0 {
						want = append(want, cmplx.Exp(complex(l*dt, 0)))
					}
				}
				zs, _ := d.Poles()
				unm := 0
				var bad []complex128
				for _, z := range zs {
					if !poleOnOrOutsideStabilityBoundary(z, false, poleStabilityTolerance(z)) {
						continue
					}
					ok := false
					for _, w := range want {
						if cmplx.Abs(z-w) < 0.25*cmplx.Abs(w) {
							ok = true
						}
					}
					if !ok {
						unm++
						bad = append(bad, z)
					}
				}
				if unm > 0 {
					acc0unm++
					if len(exs) < 8 {
						exs = append(exs, fmt.Sprintf("seed %d n=%d ord=%d kk=%d Ud=%d twinUc=%d want=%v bad=%v max=%.3g", seed, n, ord, kk, ud, uc, want, bad, fit.MaxRelativeError))
					}
				}
			}
		}
		fmt.Printf("%s: fits=%d len(parts)==1:%d k>0:%d Ud<twinUc:%d Acc0&Ud>0:%d unmatched:%d\n", set.name, rows, whole, spurK, udltUc, acc0, acc0unm)
		for _, e := range exs {
			fmt.Println("  ", e)
		}
	}
}
