		}
		tfd := tf.Copy()
		tfd.Delay = [][]float64{{c.L}}
		dss, err := tfd.StateSpace()
		if err != nil {
			t.Fatal(err)
		}
		systems := map[string]*System{"zpk": zss.Sys, "tf": tss.Sys, "tf.Delay": dss.Sys}
		for _, th := range []float64{0.3, 1.1, 2.4} {
			r := rlocScaleRotate(t, tss.Sys, th)
			rot, err := New(r.A, r.B, r.C, r.D, 1)
			if err != nil {
				t.Fatal(err)
			}
			systems[fmt.Sprintf("rotated %g", th)] = rot
		}
		for name, sys := range systems {
			if name != "tf.Delay" {
				if err := sys.SetOutputDelay([]float64{c.L}); err != nil {
					t.Fatal(err)
				}
			}
			res, err := RootLocus(sys, []float64{0, 0.5, 2, 10})
			if err != nil {
				t.Fatalf("%s %s: %v", c.name, name, err)
			}
			if len(res.Breakaway) != len(c.want) {
				t.Errorf("%s %s: Breakaway = %v, want %v", c.name, name, res.Breakaway, c.want)
				continue
			}
			assertRootSet(t, res.Breakaway, c.want, 1e-9)
		}
	}
}
