		[]float64{-0.28232123669751763, -0.06845293520088358, -0.05423197873157118,
			0.8988827084579142, -0.2919655478181712, -0.23045954579782943,
			0.3351187785620919, 0.7248773107784188, 0.5732116929405973},
		[]float64{0.955336489125606, 0.23163514068674404, 0.18351390722284003},
		[]float64{0, -0.6209859870365596, 0.7838216658808493})
	res, err := RootLocus(lit, []float64{0, 1})
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Breakaway) != 1 || math.Abs(real(res.Breakaway[0])+3.4354742e-4) > 1e-11 {
		t.Errorf("literal: Breakaway = %v, want [-3.4354742e-4]", res.Breakaway)
	}

	p := []float64{1.0 / 3000, 1.0 / 2800, 1.0 / 2600}
	s1, s2, s3 := p[0]+p[1]+p[2], p[0]*p[1]+p[0]*p[2]+p[1]*p[2], p[0]*p[1]*p[2]
	want := (-s1 + math.Sqrt(s1*s1-3*s2)) / 3
	comp := rlocCompanion3(t, s3, s2, s1, []float64{1, 0, 0})
	for _, th := range []float64{0, 0.3, 1.1, 2.4} {
		sys := comp
		if th != 0 {
			sys = rlocScaleRotate(t, comp, th)
		}
		res, err := RootLocus(sys, []float64{0, 1})
		if err != nil {
			t.Fatal(err)
		}
		if len(res.Breakaway) != 1 || math.Abs(real(res.Breakaway[0])-want) > 1e-3*math.Abs(want) {
			t.Errorf("th=%g: Breakaway = %v, want [%g]", th, res.Breakaway, want)
		}
	}
}
